114	        public static SpeedItem fromString(String specs) {
115	            String[] split = Helpers.splitObj(specs);
116	
117	            if (split == null || split.length != 2) {
118	                return new SpeedItem(null, 1);
119	            }
120	
121	            return new SpeedItem(Helpers.parseStr(split[0]), Helpers.parseFloat(split[1]));
122	        }
