171	    private void checkSleepTimer() {
172	        if (getPlayer() == null) {
173	            return;
174	        }
175	
176	        float sleepHours = getPlayerData().getSleepTimerHours();
177	        if (sleepHours > 0 && System.currentTimeMillis() - mSleepTimerStartMs > sleepHours * 60 * 60 * 1_000) {
178	            getPlayer().setPlayWhenReady(false);
179	            getPlayer().setTitle(getContext().getString(R.string.player_sleep_timer)
180	                    + " (" + getContext().getResources().getQuantityString(R.plurals.hours, (int) sleepHours, Helpers.toString(sleepHours)) + ")");
