270	    private void refreshSections() {
271	        if (getView() == null) {
272	            return;
273	        }
274	
275	        // clean up (profile changed etc)
276	        getView().removeAllSections();
277	
278	        int bootSectionId = getSidebarService().getBootSectionId();
279	
280	        // Empty Home on first run fix. Switch to something non-empty.
281	        if (!getSignInService().isSigned() && VideoStateService.instance(getContext()).isEmpty()) {
282	            bootSectionId = MediaGroup.TYPE_MUSIC;
283	        }
284	
285	        int index = 0;
286	
287	        for (BrowseSection section : mErrorSections) {
288	            getView().addSection(index++, section);
289	        }
290	
291	        for (BrowseSection section : mSections) { // contains sections and pinned items!
292	            if (section.getId() == MediaGroup.TYPE_SETTINGS) {
293	                section.setEnabled(true);
294	            }
295	
296	            if (section.isEnabled()) {
297	                if (section.getId() == bootSectionId) {
298	                    mBootSectionIndex = index;
299	                }
300	                getView().addSection(index++, section);
301	            } else {
302	                getView().removeSection(section);
303	            }
304	        }
305	
306	        // Refresh and restore last focus
307	        int selectedSectionIndex = findSectionIndex(mCurrentSection != null ? mCurrentSection.getId() : -1);
308	        getView().selectSection(selectedSectionIndex != -1 ? selectedSectionIndex : mBootSectionIndex, false);
309	    }
